"""Loading, invoking, and merging call-time credential hooks."""

import importlib
from functools import lru_cache
from inspect import isawaitable
from typing import Any, Callable, Dict, Optional

import structlog

from rasa.shared.agents.outbound_call_hook.context import (
    A2AOutboundCallContext,
    MCPOutboundCallContext,
)
from rasa.shared.agents.outbound_call_hook.result import OutboundCallResult
from rasa.shared.exceptions import RasaException

structlogger = structlog.get_logger()


class OutboundCallHookError(RasaException):
    """Raised when a call-time credential hook fails or returns an invalid value.

    Never include secret values or the raw hook payload in the message: only
    sanitized context (server/tool, sanitized exception text).
    """


@lru_cache(maxsize=128)
def load_call_hook(import_path: str) -> Callable[..., Any]:
    """Import a hook callable from a dotted module path.

    Resolved callables are cached by ``import_path`` so repeated outbound calls
    avoid redundant ``getattr`` lookups. The underlying module is also cached
    in ``sys.modules`` by ``importlib``.

    Args:
        import_path: Dotted path to a module-level callable, e.g.
            ``my_auth.credentials.resolve_banking_meta``.

    Returns:
        The resolved callable.

    Raises:
        OutboundCallHookError: If the path cannot be resolved to a callable.
    """
    if not import_path or "." not in import_path:
        raise OutboundCallHookError(
            f"Invalid pre_call_hook import path '{import_path}'. Expected a "
            f"dotted path to a module-level function, e.g. "
            f"'my_auth.credentials.resolve_banking_meta'."
        )

    module_name, _, attr_name = import_path.rpartition(".")
    try:
        module = importlib.import_module(module_name)
    except Exception as e:
        raise OutboundCallHookError(
            f"Could not import module '{module_name}' for pre_call_hook {import_path}"
        ) from e

    hook = getattr(module, attr_name, None)
    if hook is None or not callable(hook):
        raise OutboundCallHookError(
            f"pre_call_hook '{import_path}' did not resolve to a callable."
        )
    return hook


def validate_pre_call_hook_import(import_path: str, context_label: str) -> None:
    """Validate that a configured ``pre_call_hook`` import path resolves to a callable.

    Raises:
        ValidationError: If the import path cannot be resolved.
    """
    from rasa.exceptions import ValidationError

    try:
        load_call_hook(import_path)
    except OutboundCallHookError as e:
        raise ValidationError(
            code="validation.pre_call_hook.unresolved",
            event_info=(
                f"Could not resolve pre_call_hook '{import_path}' for {context_label}"
            ),
            details={"pre_call_hook": import_path, "context": context_label},
        ) from e


def validate_hook_result(result: Any) -> OutboundCallResult:
    """Normalize a hook return value into an :class:`OutboundCallResult`.

    Accepts an :class:`OutboundCallResult` or, for ergonomics, a plain
    ``dict[str, Any]`` (wrapped as ``OutboundCallResult(metadata=...)``).

    Raises:
        OutboundCallHookError: If the result is neither an ``OutboundCallResult``
            nor a ``dict``.
    """
    if isinstance(result, OutboundCallResult):
        return result
    if isinstance(result, dict):
        return OutboundCallResult(metadata=result)
    raise OutboundCallHookError(
        f"Call metadata hook must return an OutboundCallResult or a dict, "
        f"got {type(result).__name__}."
    )


async def _invoke_hook(hook: Callable[..., Any], context: Any) -> Any:
    """Invoke a (possibly async) hook positionally with the call context."""
    result = hook(context)
    if isawaitable(result):
        result = await result
    return result


async def invoke_mcp_call_hook(
    hook: Callable[..., Any], context: MCPOutboundCallContext
) -> OutboundCallResult:
    """Invoke an MCP / custom-tool hook and return its validated result.

    The hook is called as ``hook(context)``. Only the metadata *key names* are
    logged, never the values.

    Raises:
        OutboundCallHookError: If the hook raises or returns an invalid value.
    """
    try:
        result = await _invoke_hook(hook, context)
    except OutboundCallHookError:
        raise
    except Exception as e:
        raise OutboundCallHookError(
            f"Call metadata hook failed for tool_name={context.tool_name} "
            f"(server_name={context.server_name}, agent_id={context.agent_id})"
        ) from e

    validated = validate_hook_result(result)
    structlogger.debug(
        "outbound_call_hook.mcp.result",
        server_name=context.server_name,
        tool_name=context.tool_name,
        agent_id=context.agent_id,
        meta_keys=sorted(validated.metadata.keys()),
    )
    return validated


async def invoke_a2a_call_hook(
    hook: Callable[..., Any], context: A2AOutboundCallContext
) -> OutboundCallResult:
    """Invoke an outbound A2A hook and return its validated result.

    The hook is called as ``hook(context)``. Only the metadata *key names* are
    logged, never the values.

    Raises:
        OutboundCallHookError: If the hook raises or returns an invalid value.
    """
    try:
        result = await _invoke_hook(hook, context)
    except OutboundCallHookError:
        raise
    except Exception as e:
        raise OutboundCallHookError(
            f"Call metadata hook failed for A2A agent_id={context.agent_id}"
        ) from e

    validated = validate_hook_result(result)
    structlogger.debug(
        "outbound_call_hook.a2a.result",
        agent_id=context.agent_id,
        meta_keys=sorted(validated.metadata.keys()),
    )
    return validated


def merge_call_metadata(
    base: Optional[Dict[str, Any]], hook_result: Optional[OutboundCallResult]
) -> Dict[str, Any]:
    """Merge hook metadata on top of static base metadata (hook wins on collision)."""
    merged: Dict[str, Any] = dict(base or {})
    if hook_result is not None:
        merged.update(hook_result.metadata)
    return merged
